75:       </div>
76:     );
77:   };
78: 
79:   return (
80:     <div className="container pb-5">
81:       <CreateEnderecoModal
82:         handleClose={() => setIsCreateEnderecoModalOpen(false)}
83:         showModal={isCreateEnderecoModalOpen}
84:       />
85: 
86:       <Anchor.GoBack path={routes.CARDS} text="Voltar aos cartões" />
87: 
88:       <div className="float-end">
89:         <Button.Primary onClick={() => setIsCreateEnderecoModalOpen(true)}>
90:           <FontAwesomeIcon className="me-2" icon={faPlusCircle} /> Novo Endereço
91:         </Button.Primary>
92:       </div>
93: 
94:       <div className="d-flex justify-content-center mt-4">
95:         <Typography.Title>Endereços</Typography.Title>
96:       </div>
97: 
98:       <EnderecosList />
99:     </div>
100:   );
101: };
102: 
103: export default Enderecos;

